#!/usr/bin/env bash
# Idempotent local setup, run by DDEV after every `ddev start`. Local use only: credentials below are not secrets.
set -euo pipefail
cd /var/www/html

composer install --no-interaction --prefer-dist

if [ ! -f web/wp-load.php ]; then
	wp core download --path=web --skip-content --locale=en_US
fi

# wp-config.php is generated by DDEV (database settings).

if ! wp core is-installed --path=web 2>/dev/null; then
	wp core install --path=web --url="$DDEV_PRIMARY_URL" --title=ChargeNet \
		--admin_user=admin --admin_password=admin --admin_email=admin@chargenet.test --skip-email
	# WordPress sample page and draft privacy page (their slugs would clash with the seeded pages).
	wp post delete 2 3 --force --path=web
fi

wp rewrite structure '/blog/%postname%/' --path=web >/dev/null
wp theme activate chargenet --path=web
wp plugin activate polylang --path=web
wp plugin activate seo-by-rank-math --path=web
wp plugin activate wpconsent-cookies-banner-privacy-suite --path=web

# No comments anywhere; Rank Math without an account (settings: bin/setup-rankmath.php).
wp option update default_comment_status closed --path=web
wp option update default_ping_status closed --path=web
wp eval-file bin/setup-rankmath.php --path=web

# Polylang languages and settings (en default, nl; /en/ and /nl/ URLs), then media, pages, front page and menus.
wp eval-file bin/setup-polylang.php --path=web
wp eval-file bin/seed-content.php --path=web
wp eval-file bin/setup-wpconsent.php --path=web
wp rewrite flush --path=web >/dev/null
